#include "project.h"
#include <ctype.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#ifdef _WIN32
#include <direct.h>
#include <windows.h>
#define LUME_MKDIR(path) _mkdir(path)
#else
#define LUME_MKDIR(path) mkdir(path,0777)
#endif
#include "memory.h"
#include "source.h"
static char *copy(const char *s){return memory_copy_string(s,strlen(s));}
static char *join(const char *a,const char *b){size_t al=strlen(a),bl=strlen(b),i;char *r=memory_allocate(al+bl+2U);if(r==NULL)return NULL;memcpy(r,a,al);i=al;if(i>0U&&r[i-1U]!='/'&&r[i-1U]!='\\')r[i++]='/';memcpy(r+i,b,bl+1U);for(;r[i]!='\0';i++)if(r[i]=='\\')r[i]='/';return r;}
static void fail(LumeProject *p,const char *s){snprintf(p->message,sizeof(p->message),"Erro de projeto: %s",s);}
void project_init(LumeProject *p){memset(p,0,sizeof(*p));}
void project_free(LumeProject *p){size_t i;if(p==NULL)return;memory_free(p->root_path);memory_free(p->manifest_path);memory_free(p->name);memory_free(p->version);memory_free(p->entry_path);memory_free(p->source_path);for(i=0U;i<p->module_path_count;i++)memory_free(p->module_paths[i]);memory_free(p->module_paths);for(i=0U;i<p->dependency_count;i++){memory_free(p->dependencies[i].name);memory_free(p->dependencies[i].declared_path);memory_free(p->dependencies[i].resolved_path);memory_free(p->dependencies[i].version);}memory_free(p->dependencies);project_init(p);}
static bool valid_name(const char *s){size_t i;if(*s=='\0')return false;for(i=0U;s[i]!='\0';i++)if(!isalnum((unsigned char)s[i])&&s[i]!='_'&&s[i]!='-')return false;return true;}
static bool valid_version(const char *s){size_t i=0U,p=0U;while(p<3U){size_t n=0U;while(isdigit((unsigned char)s[i])){i++;n++;}if(n==0U)return false;p++;if(p<3U){if(s[i]!='.')return false;i++;}}return s[i]=='\0';}
static char *trim(char *s){char *e;while(isspace((unsigned char)*s))s++;e=s+strlen(s);while(e>s&&isspace((unsigned char)e[-1]))e--;*e='\0';return s;}
static int key_index(const char *k){static const char *keys[]={"nome","versao","entrada","fonte","caminhos_modulos"};size_t i;for(i=0U;i<5U;i++)if(strcmp(k,keys[i])==0)return (int)i;return -1;}
static bool parse_string(char *v,char **out){size_t n;v=trim(v);n=strlen(v);if(n<2U||v[0]!='"'||v[n-1U]!='"')return false;*out=memory_copy_string(v+1U,n-2U);return *out!=NULL;}
static bool push_path(LumeProject *p,char *item){char **g=memory_reallocate_array(p->module_paths,p->module_path_count+1U,sizeof(*g));if(g==NULL){memory_free(item);return false;}p->module_paths=g;p->module_paths[p->module_path_count++]=item;return true;}
static bool push_dependency(LumeProject *p,const char *name,char *value){ProjectDependency *g;char *path=NULL;size_t i;if(strcmp(name,"lume")==0||!valid_name(name)||!parse_string(value,&path))return false;for(i=0U;i<p->dependency_count;i++)if(strcmp(p->dependencies[i].name,name)==0){memory_free(path);return false;}g=memory_reallocate_array(p->dependencies,p->dependency_count+1U,sizeof(*g));if(g==NULL){memory_free(path);return false;}p->dependencies=g;memset(&g[p->dependency_count],0,sizeof(*g));g[p->dependency_count].name=copy(name);g[p->dependency_count].declared_path=path;g[p->dependency_count].target_index=SIZE_MAX;if(g[p->dependency_count].name==NULL)return false;p->dependency_count++;return true;}
static bool parse_array(char *v,LumeProject *p){char *at=trim(v);if(*at!='[')return false;at++;for(;;){char *start,*item;while(isspace((unsigned char)*at))at++;if(*at==']'){at++;return *trim(at)=='\0';}if(*at!='"')return false;start=++at;while(*at!='\0'&&*at!='"')at++;if(*at!='"')return false;item=memory_copy_string(start,(size_t)(at-start));at++;if(item==NULL||!push_path(p,item))return false;while(isspace((unsigned char)*at))at++;if(*at==','){at++;continue;}if(*at!=']')return false;}}
static bool directory_exists(const char *path){
#ifdef _WIN32
    DWORD attributes=GetFileAttributesA(path);return attributes!=INVALID_FILE_ATTRIBUTES&&(attributes&FILE_ATTRIBUTE_DIRECTORY)!=0U;
#else
    struct stat info;return stat(path,&info)==0&&S_ISDIR(info.st_mode);
#endif
}
bool project_load(LumeProject *p,const char *root){Source s;char *cursor;bool seen[5]={false,false,false,false,false};project_free(p);p->root_path=copy(root);p->manifest_path=join(root,"lume.projeto");if(p->root_path==NULL||p->manifest_path==NULL)return false;source_init(&s);if(!source_load_file(&s,p->manifest_path)){fail(p,"o arquivo lume.projeto nao foi encontrado.");return false;}cursor=s.bytes;while(*cursor!='\0'){char *line=cursor,*nl=strchr(cursor,'\n'),*eq,*key,*value;int idx;if(nl!=NULL){*nl='\0';cursor=nl+1;}else cursor+=strlen(cursor);line=trim(line);if(*line=='\0'||*line=='#')continue;eq=strchr(line,'=');if(eq==NULL){fail(p,"linha invalida; esperado chave = valor.");source_free(&s);return false;}*eq='\0';key=trim(line);value=trim(eq+1);idx=key_index(key);if(idx<0&&strncmp(key,"dependencia.",12U)==0){if(!push_dependency(p,key+12U,value)){fail(p,"dependencia duplicada ou invalida.");source_free(&s);return false;}continue;}if(idx<0){snprintf(p->message,sizeof(p->message),"Erro de projeto: chave desconhecida '%s'.%s",key,strcmp(key,"entradaa")==0?" Voce quis dizer 'entrada'?":"");source_free(&s);return false;}if(seen[(size_t)idx]){snprintf(p->message,sizeof(p->message),"Erro de projeto: a chave '%s' foi definida mais de uma vez.",key);source_free(&s);return false;}seen[(size_t)idx]=true;if(idx==4){if(!parse_array(value,p)){fail(p,"'caminhos_modulos' deve ser uma lista de textos.");source_free(&s);return false;}}else{char **slot=idx==0?&p->name:idx==1?&p->version:idx==2?&p->entry_path:&p->source_path;if(!parse_string(value,slot)){fail(p,"os valores simples devem ser textos entre aspas.");source_free(&s);return false;}}}source_free(&s);if(p->name==NULL||p->version==NULL||p->entry_path==NULL){fail(p,"as chaves obrigatorias 'nome', 'versao' e 'entrada' devem ser definidas.");return false;}if(!valid_name(p->name)){fail(p,"o nome deve usar apenas letras ASCII, numeros, '_' ou '-'.");return false;}if(!valid_version(p->version)){fail(p,"a versao deve usar o formato X.Y.Z.");return false;}if(p->entry_path[0]=='/'||p->entry_path[0]=='\\'||(strlen(p->entry_path)>1U&&p->entry_path[1]==':')){fail(p,"o caminho de entrada deve ser relativo ao projeto.");return false;}if(p->source_path==NULL)p->source_path=copy("src");{char *e=join(root,p->entry_path),*sp=join(root,p->source_path);memory_free(p->entry_path);memory_free(p->source_path);p->entry_path=e;p->source_path=sp;}if(p->entry_path==NULL||p->source_path==NULL)return false;{FILE *f=fopen(p->entry_path,"rb");if(f==NULL){snprintf(p->message,sizeof(p->message),"Erro de projeto: o arquivo de entrada nao foi encontrado: %s",p->entry_path);return false;}fclose(f);}if(!directory_exists(p->source_path)){fail(p,"o diretorio fonte nao foi encontrado.");return false;}for(size_t i=0U;i<p->module_path_count;i++){char *r=join(root,p->module_paths[i]);memory_free(p->module_paths[i]);p->module_paths[i]=r;if(r==NULL)return false;}for(size_t i=0U;i<p->dependency_count;i++){p->dependencies[i].resolved_path=join(root,p->dependencies[i].declared_path);if(p->dependencies[i].resolved_path==NULL)return false;}return true;}
bool project_create(const char *parent,const char *name,char *message,size_t cap){char *root,*src,*manifest,*entry;FILE *f;if(!valid_name(name)){snprintf(message,cap,"Erro de projeto: nome invalido.");return false;}root=join(parent,name);src=join(root,"src");manifest=join(root,"lume.projeto");entry=join(src,"principal.lume");if(root==NULL||src==NULL||manifest==NULL||entry==NULL)goto bad;if(LUME_MKDIR(root)!=0){snprintf(message,cap,"Erro de projeto: o diretorio '%s' ja existe ou nao pode ser criado.",root);goto bad;}if(LUME_MKDIR(src)!=0){snprintf(message,cap,"Erro de projeto: nao foi possivel criar o diretorio fonte.");goto bad;}f=fopen(manifest,"wb");if(f==NULL)goto io_bad;fprintf(f,"nome = \"%s\"\nversao = \"%s\"\nentrada = \"src/principal.lume\"\nfonte = \"src\"\n",name,LUME_VERSION_STRING);if(fclose(f)!=0)goto io_bad;f=fopen(entry,"wb");if(f==NULL)goto io_bad;fputs("escreva(\"Olá, Lume!\")\n",f);if(fclose(f)!=0)goto io_bad;snprintf(message,cap,"Projeto '%s' criado com sucesso.",name);memory_free(root);memory_free(src);memory_free(manifest);memory_free(entry);return true;io_bad:snprintf(message,cap,"Erro de projeto: nao foi possivel escrever os arquivos iniciais.");bad:memory_free(root);memory_free(src);memory_free(manifest);memory_free(entry);return false;}
